      if (PRIVATE_PREFIX.test(change.name ?? "")) continue;
      symbols.push({
        name: change.name,
        kind: change.kind,
        type: change.type,
        file: file.path,
        line: change.after_start_line ?? change.before_start_line ?? null,
        dependents: change.dependents_count ?? 0,
