      // findings, and keying on the file alone drops the second.
      const dup = consumers.some((c) =>
        c.repoKey === row.repo_key && c.file === row.file && c.line === row.line);
      if (dup) continue;
      consumers.push({
        target: row.target, repoKey: row.repo_key, type: row.relation_type,
