  const legacy = normalize([{ commit: "deae614", raw: fixture("legacy-complete.txt") }]);
  assert.deepEqual(Object.keys(n).sort(), Object.keys(legacy).sort());
  assert.equal(n.completeness, legacy.completeness);
  assert.equal(n.source, legacy.source);
  assert.equal(canAssertAbsence(n), canAssertAbsence(legacy));

